// Every piece of dashboard markup, written once and used twice.
//
// The server imports this module to render the page it writes to disk. The same file is read as
// text, has its `export` keywords stripped, and is inlined into the served page, where the same
// functions re-render sections as the build moves. That is the whole reason it exists: a
// server-rendered fallback and a live view that are generated by two different code paths drift,
// and the drift is invisible until someone with JavaScript disabled sees a page the team has not
// looked at in months.
//
// Two rules keep it usable in both places:
//
//   * No imports and no Node APIs. It has to run inside a <script> tag with nothing around it.
//   * `export` only ever at the start of a line, so stripping it is a one-line regex and not a
//     parser. `browserSource()` in page-chrome.js does the stripping.
//
// It is pure: state in, HTML string out. It decides nothing about the project and reads no files.

const ENTITIES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
export const escape = (text) => String(text ?? '').replace(/[&<>"']/g, (char) => ENTITIES[char]);

// ── Icons ───────────────────────────────────────────────────────────────────────────────────
// Stroked 24×24 paths on Atlas's icon grid, drawn by `.ic` so they inherit currentColor.

